#!/bin/bash
# STRICT VARIANT for the overnight runner -- GENERATED by sim/final_test/k23_run/k23_strict_wrappers.py from practice/inner.sh
# (do not edit by hand; regenerate + review). The original stays as it is for attended runs.
# K23 PRACTICE: the part that runs INSIDE the sim lock (called by run.sh via flock). Paths come from the environment, never from a quoted
# string (the repo path's apostrophe). k23_practice.py re-checks readiness (both A29 samples, final package, perception freeze, pins).
set -u
echo "$(date '+%F %T') lock acquired ($NS, strict)" >> "$OUT/progress.txt"
rm -f "$OUT/pgid"
setsid --wait bash -c 'echo $$ > "$OUT/pgid"; exec "$@"' inner timeout 14400 "$PY" sim/final_test/matrix/hang_guard.py sim/final_test/matrix/k23_practice.py --namespace "$NS" \
    --ollama "http://$HOST:11434" "$@" >> "$OUT/stdout.txt" 2>> "$OUT/stderr.txt"
rc=$?
echo $rc > "$OUT/last_rc"
echo "$(date '+%F %T') exit $rc" >> "$OUT/progress.txt"
PG=$(cat "$OUT/pgid" 2>/dev/null); rm -f "$OUT/pgid"           # STRICT: only this try's own process group (no global pkill)
[ -n "$PG" ] && pkill -9 -g "$PG" -f "thor-Linux64|hang_guard[.]py|k23_(run|practice)[.]py" 2>/dev/null
exit 0
